<div class="flex gap-2 mb-4 flex-wrap"><?php foreach ([''=>'All','new'=>'New','in_progress'=>'In progress','resolved'=>'Resolved'] as $k=>$l): ?><a class="chip <?= $st===$k?'active':'' ?>" href="<?= e(url('/admin/enquiries' . ($k?'?status='.$k:''))) ?>"><?= $l ?></a><?php endforeach; ?></div>
<div class="space-y-3"><?php foreach ($rows as $q): ?><form method="post" action="<?= e(url('/admin/enquiries/' . $q['id'])) ?>" class="card p-5 grid md:grid-cols-3 gap-4"><?= csrf_field() ?><input type="hidden" name="back" value="<?= e($st) ?>">
  <div class="md:col-span-2"><div class="flex flex-wrap items-center gap-2"><b><?= e($q['name']) ?></b><span class="badge <?= $q['status']==='new'?'bg-amber-100 text-amber-800':($q['status']==='resolved'?'bg-green-100 text-green-700':'bg-blue-100 text-blue-700') ?>"><?= e($q['status']) ?></span><span class="text-xs muted"><?= e(date('d M Y, h:i A', strtotime($q['created_at']))) ?></span></div>
    <div class="text-sm muted mt-1"><?= $q['mobile'] ? '<a class="text-primary" href="tel:'.e($q['mobile']).'">'.e($q['mobile']).'</a> · ' : '' ?><?= $q['email'] ? '<a class="text-primary" href="mailto:'.e($q['email']).'">'.e($q['email']).'</a>' : '' ?></div>
    <?php if ($q['subject']): ?><div class="font-semibold mt-2"><?= e($q['subject']) ?></div><?php endif; ?><p class="text-sm mt-1 whitespace-pre-line"><?= e($q['message']) ?></p></div>
  <div class="space-y-2"><select name="status" class="select"><?php foreach (['new','in_progress','resolved'] as $s): ?><option <?= $q['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><textarea name="internal_notes" class="textarea !min-h-[70px]" placeholder="Internal notes"><?= e($q['internal_notes']) ?></textarea><button class="btn btn-soft w-full btn-sm">Save</button></div></form>
<?php endforeach; if (!$rows): ?><div class="card p-12 text-center muted">No enquiries.</div><?php endif; ?></div><?php include __DIR__ . '/../partials/pagination.php'; ?>
